export const EXPORT_SOURCES: Record<string, string> = {".env.example":"# Gemini\nGEMINI_API_KEY=\nGEMINI_MODEL=gemini-2.5-flash\n\n# Firebase Studio\nFIREBASE_API_KEY=\nFIREBASE_AUTH_DOMAIN=\nFIREBASE_PROJECT_ID=\nFIREBASE_STORAGE_BUCKET=\nFIREBASE_MESSAGING_SENDER_ID=\nFIREBASE_APP_ID=\n\n# Arena Competition (OpenAI vs Gemini)\nOPENAI_API_KEY=\nOPENAI_MODEL=gpt-4o-mini\n\n# Optional Workflow Destinations\nWORKFLOW_WEBHOOK_URL_COMPLIANCE=\nWORKFLOW_WEBHOOK_URL_LEAD=\nWORKFLOW_WEBHOOK_URL_LEAK=\nWORKFLOW_WEBHOOK_URL_NEWS=\nWORKFLOW_WEBHOOK_URL_OUTAGE=\nWORKFLOW_WEBHOOK_URL_PRICE=\nWORKFLOW_WEBHOOK_URL_RFP=\nWORKFLOW_WEBHOOK_URL_VAT=\n","server/liveWorkflow.ts":"import { noulLocal } from \"../src/core/jevEngine\";\nimport { schemaFor, topo } from \"../src/core/synthesizer\";\nimport type { Intent, WorkflowDag } from \"../src/types\";\n\nexport interface LiveConfig {\n  tavilyKey?: string;\n  geminiKey: string;\n  jevKey?: string;\n  geminiModel?: string;\n  webhookUrl?: string;\n  webhookBearer?: string;\n  fetcher?: typeof fetch;\n}\n\nexport interface LiveResult {\n  mode: \"live\";\n  ok: boolean;\n  intent: Intent;\n  objective: string;\n  payload: Record<string, unknown>;\n  citations: string[];\n  evidence: string;\n  gate: { choice: string; score: number; noul: number; schemaPass: boolean; violations: string[] };\n  dispatch: { attempted: boolean; url?: string; status?: number; ok?: boolean; response?: string };\n  trace: Array<{ stage: string; detail: string }>;\n}\n\nconst intents: Intent[] = [\"price\", \"news\", \"compliance\", \"lead\", \"vat\", \"outage\", \"leak\", \"rfp\"];\n\nfunction required(value: string | undefined, name: string): string {\n  if (!value) throw new Error(`${name} is required for live execution.`);\n  return value;\n}\n\nasync function postJson(url: string, headers: Record<string, string>, body: unknown, client: typeof fetch): Promise<Record<string, unknown>> {\n  const response = await client(url, {\n    method: \"POST\", headers: { \"Content-Type\": \"application/json\", ...headers },\n    body: JSON.stringify(body), signal: AbortSignal.timeout(45_000),\n  });\n  if (!response.ok) throw new Error(`${new URL(url).hostname} returned HTTP ${response.status}: ${(await response.text()).slice(0, 240)}`);\n  const value: unknown = await response.json();\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) throw new Error(\"Provider returned an invalid JSON object.\");\n  return value as Record<string, unknown>;\n}\n\n/** Calls each provider. Missing credentials and failed requests never fall back to fixture data. */\nexport async function runLiveWorkflow(dag: WorkflowDag, config: LiveConfig, send = false): Promise<LiveResult> {\n  if (!intents.includes(dag.intent) || !dag.objective.trim()) throw new Error(\"Invalid workflow objective or intent.\");\n  const nodes = topo(dag);\n  if (nodes.length !== 4 || nodes.some((node, i) => node.id !== [\"scout\", \"extract\", \"gate\", \"settle\"][i])) {\n    throw new Error(\"Live execution requires Scout, Extractor, Gatekeeper, and Settlement in order.\");\n  }\n  required(config.geminiKey, \"GEMINI_API_KEY\");\n  if (send) required(config.webhookUrl, `WORKFLOW_WEBHOOK_URL_${dag.intent.toUpperCase()}`);\n  const client = config.fetcher ?? fetch;\n  const trace: LiveResult[\"trace\"] = [];\n\n  let excerpts: Array<{ url: string; title: string; text: string }> = [];\n  let sources: string[] = [];\n\n  if (config.tavilyKey) {\n    const search = await postJson(\"https://api.tavily.com/search\", { Authorization: `Bearer ${config.tavilyKey}` }, {\n      query: dag.objective, search_depth: \"basic\", max_results: 6, include_raw_content: true,\n    }, client);\n    const docs = (Array.isArray(search.results) ? search.results : []).map(item => {\n      const row = item as Record<string, unknown>;\n      return { url: String(row.url ?? \"\"), title: String(row.title ?? \"\"), text: String(row.raw_content || row.content || \"\") };\n    }).filter(doc => /^https?:\\/\\//.test(doc.url) && doc.text.trim());\n    if (!docs.length) throw new Error(\"Tavily returned no source content for this objective.\");\n    let remaining = Math.max(200, nodes[0].pruneBudget) * 4;\n    excerpts = docs.map(doc => {\n      const text = doc.text.slice(0, Math.max(0, Math.min(remaining, 4500)));\n      remaining -= text.length;\n      return { url: doc.url, title: doc.title, text };\n    }).filter(doc => doc.text);\n    sources = excerpts.map(doc => doc.url);\n    trace.push({ stage: \"Scout\", detail: `${docs.length} live Tavily results; ${excerpts.length} source excerpts retained.` });\n  } else if (process.env.ALLOW_FIXTURE_CORPUS === \"true\") {\n    const { selectCorpus } = await import(\"../src/core/tavilyAdapter.js\");\n    const docs = selectCorpus(dag.objective);\n    let remaining = Math.max(200, nodes[0].pruneBudget) * 4;\n    excerpts = docs.map(doc => {\n      const text = doc.markdown.slice(0, Math.max(0, Math.min(remaining, 4500)));\n      remaining -= text.length;\n      return { url: doc.url, title: doc.title, text };\n    }).filter(doc => doc.text);\n    sources = excerpts.map(doc => doc.url);\n    trace.push({ stage: \"Scout\", detail: `FIXTURE corpus (not live): ${excerpts.length} sources for ${dag.intent}.` });\n  } else {\n    throw new Error(\"TAVILY_API_KEY is required for live execution.\");\n  }\n\n  const schema = nodes[1].jev.noul ?? schemaFor(dag.intent);\n  const extraction = await postJson(\n    `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(config.geminiModel || \"gemini-2.5-flash\")}:generateContent`,\n    { \"x-goog-api-key\": required(config.geminiKey, \"GEMINI_API_KEY\") },\n    { contents: [{ parts: [{ text: `Objective: ${dag.objective}\\nExtractor instructions: ${nodes[1].prompt}\\nReturn a JSON object with payload, citations, and evidence. payload must satisfy ${JSON.stringify(schema)}. citations must be an array of source URLs from the excerpts that directly support the populated fields. evidence must explain support for each populated field. Use null for unavailable fields; never invent values.\\nSources:\\n${excerpts.map(doc => `URL: ${doc.url}\\nTitle: ${doc.title}\\nText: ${doc.text}`).join(\"\\n\\n\")}` }] }], generationConfig: { responseMimeType: \"application/json\" } },\n    client,\n  );\n  const candidates = extraction.candidates as Array<{ content?: { parts?: Array<{ text?: string }> } }> | undefined;\n  const generated = candidates?.[0]?.content?.parts?.map(part => part.text ?? \"\").join(\"\");\n  if (!generated) throw new Error(\"Gemini returned no extraction content.\");\n  const parsed = JSON.parse(generated) as { payload?: unknown; citations?: unknown; evidence?: unknown };\n  if (!parsed.payload || typeof parsed.payload !== \"object\" || Array.isArray(parsed.payload)) throw new Error(\"Gemini returned no structured payload.\");\n  const payload = parsed.payload as Record<string, unknown>;\n  const citations = Array.isArray(parsed.citations) ? parsed.citations.filter((url): url is string => typeof url === \"string\" && sources.includes(url)) : [];\n  const evidence = typeof parsed.evidence === \"string\" ? parsed.evidence : \"\";\n  const local = noulLocal(payload, schema);\n  trace.push({ stage: \"Extractor\", detail: `${Object.keys(payload).length} fields extracted; ${citations.length} source URLs cited; ${local.violations.length} schema violations.` });\n\n  let choice = \"proceed\";\n  let score = 0.9;\n  let noul = 0.95;\n  if (config.jevKey) {\n    const jev = await postJson(\"https://api.typesafe.ai/v1/systemone\", { Authorization: `Bearer ${config.jevKey}` }, {\n      model: \"jev-latest\",\n      state: JSON.stringify({ objective: dag.objective, payload, evidence, citations, sources: excerpts }),\n      questions: {\n        route: { type: \"choice\", instructions: `${nodes[2].prompt}. Decide whether the payload is supported by the cited source text.`, criteria: { proceed: \"All required data is supported\", review: \"Some evidence is ambiguous\", abort: \"Claims are contradicted or unsupported\" } },\n        quality: { type: \"score\", instructions: \"Completeness and source support of the structured payload\", criteria: [\"Unsupported\", \"Weak\", \"Partial\", \"Mostly supported\", \"Fully supported\"] },\n        supported: { type: \"noul\", instructions: \"Every non-null payload field is directly supported by the cited source excerpts\" },\n      },\n    }, client);\n    const answers = jev.answers as Record<string, Record<string, unknown>> | undefined;\n    if (!answers?.route || !answers.quality || !answers.supported) throw new Error(\"Jev returned incomplete answers.\");\n    choice = String(answers.route.choice ?? \"abort\");\n    score = Number(answers.quality.score) / 4;\n    noul = Number(answers.supported.noul);\n    if (![score, noul].every(n => Number.isFinite(n) && n >= 0 && n <= 1)) throw new Error(\"Jev returned invalid gate values.\");\n  } else {\n    const gatePrompt = `You are the Gatekeeper specialist. ${nodes[2].prompt}.\nObjective: ${dag.objective}\nPayload: ${JSON.stringify(payload)}\nEvidence: ${evidence}\nCitations: ${JSON.stringify(citations)}\nSources: ${JSON.stringify(excerpts)}\n\nDecide whether the payload is supported by the cited source text. Return a JSON object with:\n{\"route\":\"proceed\"|\"review\"|\"abort\",\"score\":<number 0.0-1.0>,\"noul\":<number 0.0-1.0>}`;\n    const gateResp = await postJson(\n      `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(config.geminiModel || \"gemini-2.5-flash\")}:generateContent`,\n      { \"x-goog-api-key\": required(config.geminiKey, \"GEMINI_API_KEY\") },\n      { contents: [{ parts: [{ text: gatePrompt }] }], generationConfig: { responseMimeType: \"application/json\" } },\n      client,\n    );\n    const cand = gateResp.candidates as Array<{ content?: { parts?: Array<{ text?: string }> } }> | undefined;\n    const txt = cand?.[0]?.content?.parts?.map(part => part.text ?? \"\").join(\"\");\n    let parsedGate: { route?: string; score?: number; noul?: number } = {};\n    try { parsedGate = txt ? JSON.parse(txt) : {}; } catch { parsedGate = {}; }\n    // Fail closed: a missing or unparseable gate verdict never proceeds.\n    choice = typeof parsedGate.route === \"string\" ? parsedGate.route : \"abort\";\n    score = typeof parsedGate.score === \"number\" ? parsedGate.score : 0;\n    noul = typeof parsedGate.noul === \"number\" ? parsedGate.noul : 0;\n  }\n  const gate = { choice, score, noul, schemaPass: local.pass, violations: local.violations };\n  const passed = local.pass && citations.length > 0 && evidence.trim().length > 0 && choice === \"proceed\" && score >= nodes[2].jev.scoreMin && noul >= nodes[2].jev.scoreMin;\n  trace.push({ stage: \"Gatekeeper\", detail: `${config.jevKey ? \"Jev\" : \"Gatekeeper\"} ${choice}; score ${score.toFixed(2)}, source support ${noul.toFixed(2)}; ${passed ? \"passed\" : \"held\"}.` });\n\n  const dispatch: LiveResult[\"dispatch\"] = { attempted: false };\n  if (send && passed) {\n    const destination = required(config.webhookUrl, `WORKFLOW_WEBHOOK_URL_${dag.intent.toUpperCase()}`);\n    if (!/^https?:$/.test(new URL(destination).protocol)) throw new Error(\"Destination URL must use HTTP or HTTPS.\");\n    const response = await client(destination, {\n      method: nodes[3].rest?.method ?? \"POST\",\n      headers: { \"Content-Type\": \"application/json\", ...(config.webhookBearer ? { Authorization: `Bearer ${config.webhookBearer}` } : {}) },\n      body: JSON.stringify({ intent: dag.intent, objective: dag.objective, payload, citations, evidence }),\n      signal: AbortSignal.timeout(45_000),\n    });\n    Object.assign(dispatch, { attempted: true, url: destination, status: response.status, ok: response.ok, response: (await response.text()).slice(0, 1000) });\n    trace.push({ stage: \"Settlement\", detail: `${nodes[3].rest?.method ?? \"POST\"} to configured destination returned HTTP ${response.status}.` });\n  } else {\n    trace.push({ stage: \"Settlement\", detail: send ? \"Gate held the result; no request sent.\" : \"Live result ready; dispatch was not requested.\" });\n  }\n  return { mode: \"live\", ok: passed && (!send || dispatch.ok === true), intent: dag.intent, objective: dag.objective, payload, citations, evidence, gate, dispatch, trace };\n}\n\nexport function configFromEnv(intent: Intent): LiveConfig {\n  return {\n    tavilyKey: process.env.TAVILY_API_KEY,\n    geminiKey: process.env.GEMINI_API_KEY || \"\",\n    jevKey: process.env.TYPESAFE_API_KEY,\n    geminiModel: process.env.GEMINI_MODEL,\n    webhookUrl: process.env[`WORKFLOW_WEBHOOK_URL_${intent.toUpperCase()}`],\n    webhookBearer: process.env.WORKFLOW_WEBHOOK_BEARER,\n  };\n}\n","server/browserDuel.ts":"import { chromium, type Browser } from \"playwright\";\nimport { noulLocal } from \"../src/core/jevEngine\";\nimport type { ArenaChallenge } from \"../src/data/arenaChallenges\";\n\nexport interface BrowserDuelConfig {\n  geminiKey?: string;\n  openaiKey?: string;\n  jevKey?: string;\n  geminiModel?: string;\n  openaiModel?: string;\n  fetcher?: typeof fetch;\n  launchBrowser?: () => Promise<Browser>;\n}\n\nexport interface BrowserLaneResult {\n  lane: \"A\" | \"B\";\n  success: boolean;\n  durationMs: number;\n  promptTokens: number;\n  screenshot: string;\n  payload: Record<string, unknown> | null;\n  events: Array<{ stage: string; action: string; selector?: string; detail: string }>;\n  gate?: { choice: string; score: number; noul: number; violations: string[] };\n  error?: string;\n}\n\nexport interface BrowserDuelResult {\n  mode: \"live browser\";\n  url: string;\n  winner: \"A\" | \"B\" | \"draw\";\n  lanes: [BrowserLaneResult, BrowserLaneResult];\n}\n\nfunction jsonObject(text: string): Record<string, unknown> {\n  const parsed: unknown = JSON.parse(text);\n  if (!parsed || typeof parsed !== \"object\" || Array.isArray(parsed)) throw new Error(\"Model returned an invalid JSON object.\");\n  return parsed as Record<string, unknown>;\n}\n\nasync function provider(url: string, key: string, body: unknown, client: typeof fetch, authHeader: string) {\n  const response = await client(url, {\n    method: \"POST\", headers: { \"Content-Type\": \"application/json\", [authHeader]: authHeader === \"Authorization\" ? `Bearer ${key}` : key },\n    body: JSON.stringify(body), signal: AbortSignal.timeout(45_000),\n  });\n  if (!response.ok) throw new Error(`${new URL(url).hostname} returned HTTP ${response.status}: ${(await response.text()).slice(0, 180)}`);\n  return jsonObject(await response.text());\n}\n\nasync function model(prompt: string, config: BrowserDuelConfig, id: \"A\" | \"B\" = \"B\"): Promise<{ output: Record<string, unknown>; tokens: number }> {\n  if ((id === \"A\" && config.openaiKey) || (!config.geminiKey && config.openaiKey)) {\n    const url = \"https://api.openai.com/v1/chat/completions\";\n    const body = {\n      model: config.openaiModel || \"gpt-4o-mini\",\n      messages: [\n        { role: \"system\", content: \"You are an autonomous web agent. Return valid JSON only.\" },\n        { role: \"user\", content: prompt },\n      ],\n      response_format: { type: \"json_object\" },\n    };\n    const response = await provider(url, config.openaiKey, body, config.fetcher ?? fetch, \"Authorization\");\n    const choices = response.choices as Array<{ message?: { content?: string } }> | undefined;\n    const text = choices?.[0]?.message?.content;\n    if (!text) throw new Error(\"OpenAI returned no browser decision.\");\n    const usage = response.usage as { prompt_tokens?: number } | undefined;\n    return { output: jsonObject(text), tokens: Number(usage?.prompt_tokens) || 0 };\n  }\n\n  const geminiKey = config.geminiKey || \"\";\n  if (!geminiKey) throw new Error(\"GEMINI_API_KEY is required for this lane.\");\n  const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(config.geminiModel || \"gemini-2.5-flash\")}:generateContent`;\n  const response = await provider(url, geminiKey, { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: \"application/json\" } }, config.fetcher ?? fetch, \"x-goog-api-key\");\n  const candidates = response.candidates as Array<{ content?: { parts?: Array<{ text?: string }> } }> | undefined;\n  const text = candidates?.[0]?.content?.parts?.map(part => part.text ?? \"\").join(\"\");\n  if (!text) throw new Error(\"Gemini returned no browser decision.\");\n  const usage = response.usageMetadata as { promptTokenCount?: number } | undefined;\n  return { output: jsonObject(text), tokens: Number(usage?.promptTokenCount) || 0 };\n}\n\nfunction assertPayload(challenge: ArenaChallenge, payload: Record<string, unknown>): string[] {\n  return (challenge.assertions ?? []).flatMap(assertion => {\n    const value = payload[assertion.field];\n    const exists = Object.hasOwn(payload, assertion.field) && value !== null && value !== undefined;\n    return (assertion.operator === \"exists\" ? exists : exists && String(value) === assertion.value)\n      ? [] : [`${assertion.field}: ${assertion.operator === \"exists\" ? \"missing\" : `expected ${assertion.value}`}`];\n  });\n}\n\nasync function lane(challenge: ArenaChallenge, config: BrowserDuelConfig, browser: Browser, id: \"A\" | \"B\"): Promise<BrowserLaneResult> {\n  const started = Date.now();\n  const result: BrowserLaneResult = { lane: id, success: false, durationMs: 0, promptTokens: 0, screenshot: \"\", payload: null, events: [] };\n  const context = await browser.newContext({ viewport: { width: 1050, height: 720 } });\n  const page = await context.newPage();\n  page.setDefaultTimeout(10_000);\n  try {\n    await page.goto(challenge.url, { waitUntil: \"domcontentloaded\", timeout: 30_000 });\n    result.events.push({ stage: \"Scout\", action: \"navigate\", detail: `Opened ${page.url()} in a real Chromium page.` });\n    const history: string[] = [];\n    const observations: string[] = [];\n    const selectors = challenge.nodes.map(node => ({ selector: node.selector, label: node.text }));\n    for (let step = 0; step < 6; step++) {\n      const available = await Promise.all(selectors.map(async node => {\n        const locator = page.locator(node.selector).first();\n        const count = await locator.count().catch(() => 0);\n        const visible = count ? await locator.isVisible().catch(() => false) : false;\n        return { ...node, visible, text: visible ? (await locator.innerText({ timeout: 1500 }).catch(() => node.label)).slice(0, 200) : \"\" };\n      }));\n      const pageText = (await page.locator(\"body\").innerText().catch(() => \"\")).slice(0, 6000);\n      observations.push(pageText);\n      const prompt = id === \"A\"\n        ? `You are one browser agent responsible for all navigation and extraction. Mission: ${challenge.blurb}. Current URL: ${page.url()}. All previous observations: ${history.join(\"\\n\").slice(-9000)}. Current page text: ${pageText}. Available mission selectors: ${JSON.stringify(available)}. Choose ONE action using JSON {\"action\":\"click|fill|select|inspect|done\",\"selector\":\"an exact selector from the list or empty for done\",\"value\":\"input value if needed\",\"reason\":\"short explanation\"}. Choose done when the page provides enough evidence for ${JSON.stringify(challenge.schema)}.`\n        : `You are the Scout specialist in a relay team. Mission: ${challenge.blurb}. Current URL: ${page.url()}. Current page text: ${pageText.slice(0, 3000)}. Available mission selectors: ${JSON.stringify(available)}. Choose ONE action using JSON {\"action\":\"click|fill|select|inspect|done\",\"selector\":\"an exact selector from the list or empty for done\",\"value\":\"input value if needed\",\"reason\":\"short explanation\"}. Choose done when the Extractor has enough page evidence for ${JSON.stringify(challenge.schema)}. Use only the current observation.`;\n      const decision = await model(prompt, config, id);\n      result.promptTokens += decision.tokens;\n      const action = String(decision.output.action ?? \"done\");\n      const selector = String(decision.output.selector ?? \"\");\n      const value = String(decision.output.value ?? \"\");\n      const reason = String(decision.output.reason ?? \"\").slice(0, 240);\n      if (action === \"done\") { result.events.push({ stage: \"Scout\", action, detail: reason || \"Ready to extract.\" }); break; }\n      if (!selectors.some(node => node.selector === selector)) throw new Error(`Agent chose an unconfigured selector: ${selector}`);\n      const locator = page.locator(selector).first();\n      if (action === \"click\") await locator.click();\n      else if (action === \"fill\") await locator.fill(value);\n      else if (action === \"select\") await locator.selectOption(value);\n      else if (action === \"inspect\") observations.push((await locator.innerText()).slice(0, 1200));\n      else throw new Error(`Agent chose an unknown browser action: ${action}`);\n      history.push(`${action} ${selector}: ${reason}; page: ${pageText.slice(0, 1200)}`);\n      result.events.push({ stage: \"Scout\", action, selector, detail: reason });\n    }\n\n    const evidenceText = (await page.locator(\"body\").innerText().catch(() => \"\")).slice(0, 9000);\n    const extraction = await model(`You are the ${id === \"B\" ? \"Extractor specialist\" : \"same solo agent\"}. Extract a JSON object {\"payload\":{},\"evidence\":\"which visible page text supports the fields\"} from this actual browser observation. Schema: ${JSON.stringify(challenge.schema)}. URL: ${page.url()}. Visible page text: ${evidenceText}. Inspected text: ${observations.slice(-2).join(\"\\n\").slice(0, 2500)}. Use null when a field is unsupported. Do not use a prewritten fixture.`, config, id);\n    result.promptTokens += extraction.tokens;\n    if (!extraction.output.payload || typeof extraction.output.payload !== \"object\" || Array.isArray(extraction.output.payload)) throw new Error(\"Extractor returned no payload.\");\n    const payload = extraction.output.payload as Record<string, unknown>;\n    const evidence = String(extraction.output.evidence ?? \"\");\n    result.payload = payload;\n    result.events.push({ stage: \"Extractor\", action: \"extract\", detail: `${Object.keys(payload).length} fields read from the opened page.` });\n\n    let choice = \"proceed\";\n    let score = 0.9;\n    let noul = 0.95;\n    if (config.jevKey) {\n      const jev = await provider(\"https://api.typesafe.ai/v1/systemone\", config.jevKey, {\n        model: \"jev-latest\", state: JSON.stringify({ mission: challenge.blurb, url: page.url(), payload, evidence, pageText: evidenceText }),\n        questions: {\n          route: { type: \"choice\", instructions: \"Should this browser extraction proceed based on visible evidence?\", criteria: { proceed: \"Supported\", review: \"Ambiguous\", abort: \"Unsupported\" } },\n          quality: { type: \"score\", instructions: \"Completeness and accuracy of browser extraction\", criteria: [\"Invalid\", \"Weak\", \"Partial\", \"Mostly complete\", \"Complete\"] },\n          supported: { type: \"noul\", instructions: \"Every non-null payload field is supported by the observed page text\" },\n        },\n      }, config.fetcher ?? fetch, \"Authorization\");\n      const answers = jev.answers as Record<string, Record<string, unknown>> | undefined;\n      if (!answers?.route || !answers.quality || !answers.supported) throw new Error(\"Jev returned incomplete browser evaluation.\");\n      choice = String(answers.route.choice ?? \"abort\");\n      score = Number(answers.quality.score) / 4;\n      noul = Number(answers.supported.noul);\n      if (![score, noul].every(n => Number.isFinite(n) && n >= 0 && n <= 1)) throw new Error(\"Jev returned invalid browser gate values.\");\n    } else {\n      const gatePrompt = `You are the Gatekeeper judging a browser extraction. Mission: ${challenge.blurb}. Page URL: ${page.url()}. Schema: ${JSON.stringify(challenge.schema)}. Extracted payload: ${JSON.stringify(payload)}. Evidence text: ${evidence}. Visible page text: ${evidenceText.slice(0, 3000)}. Decide whether this extraction is supported. Return JSON {\"choice\":\"proceed\"|\"review\"|\"abort\", \"score\":<number 0.0-1.0>, \"noul\":<number 0.0-1.0>}.`;\n      const evalResult = await model(gatePrompt, config, \"B\");\n      // Fail closed: anything unparseable holds the result.\n      choice = typeof evalResult.output.choice === \"string\" ? evalResult.output.choice : \"abort\";\n      score = typeof evalResult.output.score === \"number\" ? evalResult.output.score : 0;\n      noul = typeof evalResult.output.noul === \"number\" ? evalResult.output.noul : 0;\n    }\n    const local = noulLocal(payload, challenge.schema);\n    const violations = [...local.violations, ...assertPayload(challenge, payload)];\n    result.gate = { choice, score, noul, violations };\n    result.success = violations.length === 0 && evidence.trim().length > 0 && choice === \"proceed\" && score >= 0.7 && noul >= 0.7;\n    result.events.push({ stage: \"Gatekeeper\", action: result.success ? \"proceed\" : \"hold\", detail: `${config.jevKey ? \"Jev\" : \"Gatekeeper\"} ${choice}; score ${score.toFixed(2)}, support ${noul.toFixed(2)}; ${violations.join(\"; \") || \"assertions checked\"}.` });\n    result.events.push({ stage: \"Settlement\", action: result.success ? \"complete\" : \"halt\", detail: result.success ? \"Live browser mission passed.\" : \"Mission did not pass the evidence gate.\" });\n  } catch (error) {\n    result.error = error instanceof Error ? error.message : \"Browser run failed\";\n    result.events.push({ stage: \"Browser\", action: \"error\", detail: result.error });\n  } finally {\n    try { result.screenshot = (await page.screenshot({ type: \"jpeg\", quality: 60 })).toString(\"base64\"); } catch { /* The page may have closed after a navigation error. */ }\n    result.durationMs = Date.now() - started;\n    await context.close();\n  }\n  return result;\n}\n\nexport async function runBrowserDuel(challenge: ArenaChallenge, config: BrowserDuelConfig): Promise<BrowserDuelResult> {\n  const target = new URL(challenge.url);\n  if (!/^https?:$/.test(target.protocol)) throw new Error(\"A real HTTP or HTTPS challenge URL is required.\");\n  if (!config.geminiKey && !config.openaiKey) throw new Error(\"GEMINI_API_KEY or OPENAI_API_KEY is required for live browser duels.\");\n  if (!challenge.nodes.length || challenge.nodes.length > 30) throw new Error(\"Configure between 1 and 30 browser elements.\");\n  const browser = await (config.launchBrowser?.() ?? chromium.launch({ headless: true }));\n  try {\n    const [a, b] = await Promise.all([lane(challenge, config, browser, \"A\"), lane(challenge, config, browser, \"B\")]);\n    const winner = a.success && b.success ? (a.durationMs <= b.durationMs ? \"A\" : \"B\") : a.success ? \"A\" : b.success ? \"B\" : \"draw\";\n    return { mode: \"live browser\", url: target.href, winner, lanes: [a, b] };\n  } finally { await browser.close(); }\n}\n","src/types.ts":"export type Channel = \"TAVILY_RESEARCH\" | \"REST_API_DISPATCH\" | \"TRANSFORMATION\" | \"HUMAN_GATE\";\nexport type MindId = \"scout\" | \"extractor\" | \"gatekeeper\" | \"settlement\";\nexport type Intent = \"price\" | \"news\" | \"compliance\" | \"lead\" | \"vat\" | \"outage\" | \"leak\" | \"rfp\";\nexport interface JsonSchema { type?: \"object\"|\"string\"|\"number\"|\"boolean\"|\"array\"; required?: string[]; properties?: Record<string, JsonSchema>; minLength?: number; minimum?: number; maximum?: number; minItems?: number; }\nexport interface JevGate { scoreMin: number; choice: string[]; noul: JsonSchema | null; }\nexport interface RestSpec { method: \"GET\"|\"POST\"|\"PUT\"|\"PATCH\"; url: string; headers: Record<string,string>; }\nexport interface WorkflowNode { id: string; title: string; channel: Channel; mind: MindId; dependsOn: string[]; pruneBudget: number; prompt: string; jev: JevGate; rest?: RestSpec; }\nexport interface WorkflowDag { id: string; objective: string; intent: Intent; nodes: WorkflowNode[]; edges: Array<[string, string]>; }\nexport interface JevChoice { selected: string; confidence: number; rationale: string; }\nexport interface JevScore { value: number; dimensions: { completeness: number; density: number; consistency: number }; }\nexport interface JevNoul { pass: boolean; violations: string[]; }\nexport interface NodeOutput { ok: boolean; rawTokens: number; tokens: number; dropped: number; markdown: string; structured: Record<string, unknown> | null; sources?: string[]; restStatus?: number; rest?: RestSpec; }\nexport interface ExecutionStep { node: WorkflowNode; out: NodeOutput; score: JevScore; noul: JevNoul; choice: JevChoice; at: number; }\nexport interface VesselResult { ok: boolean; steps: ExecutionStep[]; totalIn: number; totalOut: number; lastScore: number; lastChoice: JevChoice | null; lastNoul: JevNoul | null; structured?: Record<string, unknown> | null; }\nexport interface MonolithTelemetry { tokens: number; drift: number; failAt: number | null; hallucination: boolean; note: string; }\nexport interface Preset { id: Intent; name: string; blurb: string; objective: string; }\nexport interface MindPersona { id: MindId; name: string; role: string; color: string; channel: Channel; tag: string; copy: string; }\n","src/data/arenaChallenges.ts":"import type { JsonSchema } from \"../types\";\nexport interface ArenaDomNode { id: string; tag: string; role: \"button\"|\"input\"|\"table\"|\"modal\"|\"banner\"|\"link\"|\"text\"|\"select\"|\"row\"; text: string; selector: string; decoy: boolean; visible: boolean; bounds: { x: number; y: number; w: number; h: number }; }\nexport interface SuccessAssertion { field: string; operator: \"exists\" | \"equals\"; value?: string; }\nexport interface ArenaChallenge { id: string; name: string; blurb: string; url: string; title: string; nodes: ArenaDomNode[]; scriptA: string[]; scriptB: string[]; rawDom: string; cleanPayload: Record<string, unknown>; schema: JsonSchema; assertions?: SuccessAssertion[]; }\nfunction n(p: Omit<ArenaDomNode, \"visible\"> & { visible?: boolean }): ArenaDomNode { return { visible: true, ...p }; }\nexport const ECOM_CHALLENGE: ArenaChallenge = { id: \"ecom\", name: \"Multi-step e-commerce price check\", blurb: \"Variants, decoy popups, shipping\", url: \"shop.example/widget-nx\", title: \"Widget NX\", nodes: [n({ id: \"cookie\", tag: \"div\", role: \"banner\", text: \"Accept cookies\", selector: \"#cookie-wall button.accept\", decoy: true, bounds: { x: 16, y: 12, w: 280, h: 32 } }), n({ id: \"var\", tag: \"select\", role: \"select\", text: \"Variant 16GB/512 USD 428\", selector: \"select#variant\", decoy: false, bounds: { x: 16, y: 52, w: 280, h: 32 } }), n({ id: \"news\", tag: \"dialog\", role: \"modal\", text: \"Subscribe popup\", selector: \"dialog.newsletter button\", decoy: true, bounds: { x: 16, y: 92, w: 280, h: 32 } }), n({ id: \"ship\", tag: \"table\", role: \"table\", text: \"Ship US 12 EU 28\", selector: \"table#shipping tbody\", decoy: false, bounds: { x: 16, y: 132, w: 280, h: 32 } }), n({ id: \"cta\", tag: \"button\", role: \"button\", text: \"Add to cart 428 USD\", selector: \"button[data-action='add']\", decoy: false, bounds: { x: 16, y: 172, w: 280, h: 32 } })], scriptA: [\"cookie\", \"news\", \"cookie\", \"news\", \"crash\"], scriptB: [\"var\", \"ship\", \"cta\", \"api\"], rawDom: \"<html>\" + \"cookie\".repeat(40), cleanPayload: { sku: \"NX-428\", price: 428, currency: \"USD\" }, schema: { type: \"object\", required: [\"sku\", \"price\", \"currency\"], properties: { sku: { type: \"string\", minLength: 2 }, price: { type: \"number\", minimum: 0 }, currency: { type: \"string\", minLength: 3 } } } };\nexport const AIR_CHALLENGE: ArenaChallenge = { id: \"air\", name: \"Airline booking matrix\", blurb: \"Dates, reject add-ons, tax\", url: \"fly.example/book\", title: \"DXB-LHR\", nodes: [n({ id: \"dates\", tag: \"input\", role: \"input\", text: \"DXB LHR 12-19 Oct\", selector: \"input[name='itinerary']\", decoy: false, bounds: { x: 16, y: 12, w: 280, h: 32 } }), n({ id: \"seat\", tag: \"dialog\", role: \"modal\", text: \"Extra-legroom +64\", selector: \"dialog#seat-upsell button\", decoy: true, bounds: { x: 16, y: 52, w: 280, h: 32 } }), n({ id: \"matrix\", tag: \"table\", role: \"table\", text: \"BA107 842 tax 186\", selector: \"table.fares tbody\", decoy: false, bounds: { x: 16, y: 92, w: 280, h: 32 } }), n({ id: \"tax\", tag: \"table\", role: \"table\", text: \"LHR terminal tax 28.90\", selector: \"table#tax-break\", decoy: false, bounds: { x: 16, y: 132, w: 280, h: 32 } })], scriptA: [\"seat\", \"seat\", \"crash\"], scriptB: [\"dates\", \"matrix\", \"tax\", \"api\"], rawDom: \"<div id='seat-upsell'>\" + \"x\".repeat(400), cleanPayload: { route: \"DXB-LHR\", fare: 842, tax: 186, currency: \"GBP\" }, schema: { type: \"object\", required: [\"route\", \"fare\", \"tax\", \"currency\"], properties: { route: { type: \"string\" }, fare: { type: \"number\" }, tax: { type: \"number\" }, currency: { type: \"string\" } } } };\nexport const RBAC_CHALLENGE: ArenaChallenge = { id: \"rbac\", name: \"Enterprise SaaS RBAC audit\", blurb: \"Orphaned accounts\", url: \"admin.example/iam\", title: \"IAM\", nodes: [n({ id: \"upsell\", tag: \"div\", role: \"banner\", text: \"Upgrade Enterprise\", selector: \".upsell-banner a\", decoy: true, bounds: { x: 16, y: 12, w: 280, h: 32 } }), n({ id: \"tbl\", tag: \"table\", role: \"table\", text: \"Users 412 3 orphaned\", selector: \"table#users\", decoy: false, bounds: { x: 16, y: 52, w: 280, h: 32 } }), n({ id: \"row\", tag: \"tr\", role: \"row\", text: \"svc-old-pager\", selector: \"tr[data-acct='svc-old-pager']\", decoy: false, bounds: { x: 16, y: 92, w: 280, h: 32 } }), n({ id: \"perm\", tag: \"table\", role: \"table\", text: \"billing.write unbound\", selector: \"table#rbac td\", decoy: false, bounds: { x: 16, y: 132, w: 280, h: 32 } })], scriptA: [\"upsell\", \"upsell\", \"crash\"], scriptB: [\"tbl\", \"row\", \"perm\", \"api\"], rawDom: \"<nav>\" + \"=\".repeat(400), cleanPayload: { users: 412, orphans: [\"svc-old-pager\", \"etl-tmp\"] }, schema: { type: \"object\", required: [\"users\", \"orphans\"], properties: { users: { type: \"number\", minimum: 1 }, orphans: { type: \"array\", minItems: 1 } } } };\nexport const GOV_CHALLENGE: ArenaChallenge = { id: \"rfp\", name: \"Government procurement RFP scrape\", blurb: \"PDFs and deadlines\", url: \"sam.example/opps/24-118\", title: \"RFP 24-118\", nodes: [n({ id: \"survey\", tag: \"dialog\", role: \"modal\", text: \"How did you hear about us\", selector: \"dialog#survey button\", decoy: true, bounds: { x: 16, y: 12, w: 280, h: 32 } }), n({ id: \"page\", tag: \"p\", role: \"text\", text: \"Page 3 of 12\", selector: \"nav[aria-label='pagination']\", decoy: false, bounds: { x: 16, y: 52, w: 280, h: 32 } }), n({ id: \"pdf\", tag: \"a\", role: \"link\", text: \"SOW.pdf\", selector: \"a[href$='SOW.pdf']\", decoy: false, bounds: { x: 16, y: 92, w: 280, h: 32 } }), n({ id: \"due\", tag: \"time\", role: \"text\", text: \"Deadline 2026-10-14\", selector: \"time[datetime]\", decoy: false, bounds: { x: 16, y: 132, w: 280, h: 32 } })], scriptA: [\"survey\", \"survey\", \"crash\"], scriptB: [\"page\", \"pdf\", \"due\", \"api\"], rawDom: \"<form>\" + \"#\".repeat(400), cleanPayload: { opp: \"24-118\", due: \"2026-10-14T21:00:00Z\", files: [\"SOW.pdf\"] }, schema: { type: \"object\", required: [\"opp\", \"due\", \"files\"], properties: { opp: { type: \"string\" }, due: { type: \"string\", minLength: 8 }, files: { type: \"array\", minItems: 1 } } } };\nexport const ARENA_CHALLENGES: ArenaChallenge[] = [ECOM_CHALLENGE, AIR_CHALLENGE, RBAC_CHALLENGE, GOV_CHALLENGE];\nexport function getArenaChallenge(id: string){ return ARENA_CHALLENGES.find(c => c.id === id) ?? ECOM_CHALLENGE; }\n","src/core/jevEngine.ts":"import type { JevChoice, JevNoul, JevScore, JsonSchema } from \"../types\";\nfunction clamp(n: number, a=0, b=1){ return Math.max(a, Math.min(b, n)); }\nexport function tokenize(s: string){ return String(s||\"\").toLowerCase().match(/[a-z0-9]+/g) ?? []; }\nexport function noulLocal(payload: unknown, schema: JsonSchema | null | undefined): JevNoul {\n  const violations: string[] = [];\n  const walk = (val: unknown, sch: JsonSchema | undefined, path: string): void => {\n    if (!sch) return;\n    if (sch.type === \"object\") {\n      if (typeof val !== \"object\" || val === null || Array.isArray(val)) { violations.push(path + \" expected object\"); return; }\n      const rec = val as Record<string, unknown>;\n      for (const r of sch.required ?? []) if (rec[r] === undefined || rec[r] === null || rec[r] === \"\") violations.push(path + \".\" + r + \" required\");\n      for (const [k, sub] of Object.entries(sch.properties ?? {})) if (rec[k] !== undefined) walk(rec[k], sub, path + \".\" + k);\n      return;\n    }\n    if (sch.type === \"number\") {\n      if (typeof val !== \"number\" || Number.isNaN(val)) { violations.push(path + \" expected number\"); return; }\n      if (sch.minimum !== undefined && val < sch.minimum) violations.push(path + \" below \" + sch.minimum);\n      if (sch.maximum !== undefined && val > sch.maximum) violations.push(path + \" above \" + sch.maximum);\n      return;\n    }\n    if (sch.type === \"string\") {\n      if (typeof val !== \"string\") { violations.push(path + \" expected string\"); return; }\n      if (sch.minLength && val.length < sch.minLength) violations.push(path + \" too short\");\n      return;\n    }\n    if (sch.type === \"boolean\") { if (typeof val !== \"boolean\") violations.push(path + \" expected boolean\"); return; }\n    if (sch.type === \"array\") {\n      if (!Array.isArray(val)) violations.push(path + \" expected array\");\n      else if (sch.minItems && val.length < sch.minItems) violations.push(path + \" minItems \" + sch.minItems);\n    }\n  };\n  walk(payload, schema ?? undefined, \"$\");\n  return { pass: violations.length === 0, violations };\n}\nexport function scoreLocal(payload: unknown, rubric?: { required?: string[] }): JevScore {\n  const required = rubric?.required ?? [];\n  const rec = payload && typeof payload === \"object\" && !Array.isArray(payload) ? payload as Record<string, unknown> : null;\n  const filled = required.filter(k => rec && rec[k] !== undefined && rec[k] !== null && rec[k] !== \"\");\n  const completeness = required.length ? filled.length / required.length : rec && Object.keys(rec).length ? 0.86 : 0.2;\n  const toks = tokenize(JSON.stringify(payload ?? {}));\n  const density = clamp(0.35 + (new Set(toks).size / Math.max(toks.length, 1)) * 0.7);\n  let consistency = 0.9;\n  if (rec) for (const v of Object.values(rec)) if (typeof v === \"number\" && !Number.isFinite(v)) consistency -= 0.4;\n  const value = clamp(completeness * 0.42 + density * 0.28 + clamp(consistency) * 0.3);\n  return { value, dimensions: { completeness, density, consistency: clamp(consistency) } };\n}\nexport function choiceLocal(candidates: string[], context: { score?: number; scoreMin?: number; noul?: JevNoul }): JevChoice {\n  const opts = candidates.length ? candidates : [\"proceed\", \"human_review\", \"abort\"];\n  const noulPass = context.noul?.pass !== false;\n  const sc = typeof context.score === \"number\" ? context.score : 0.7;\n  const scoreMin = context.scoreMin ?? 0.62;\n  if (!noulPass) return { selected: \"abort\", confidence: 0.97, rationale: \"Noul assertion failed\" };\n  if (sc < scoreMin) return { selected: opts.includes(\"human_review\") ? \"human_review\" : \"abort\", confidence: 0.8, rationale: \"Score below readiness band\" };\n  if (sc >= scoreMin && opts.includes(\"proceed\")) return { selected: \"proceed\", confidence: clamp(0.58 + sc * 0.38), rationale: \"Score and schema cleared the gate\" };\n  return { selected: opts[0], confidence: clamp(0.55 + sc * 0.3), rationale: \"Local fallback Choice\" };\n}\nexport async function jevChoice(c: string[], ctx: { score?: number; scoreMin?: number; noul?: JevNoul }) { return choiceLocal(c, ctx); }\nexport async function jevScore(p: unknown, r?: { required?: string[] }) { return scoreLocal(p, r); }\nexport async function jevNoul(p: unknown, s: JsonSchema | null | undefined) { return noulLocal(p, s); }\nexport const Jev = { Choice: jevChoice, Score: jevScore, Noul: jevNoul };\n","src/core/synthesizer.ts":"import { detectIntent, liftStructured, pruneTokens, tavilySearch, tokensOf } from \"./tavilyAdapter\";\nimport { jevChoice, jevNoul, jevScore } from \"./jevEngine\";\nimport type { Intent, JsonSchema, RestSpec, VesselResult, WorkflowDag, WorkflowNode } from \"../types\";\nexport function schemaFor(intent: Intent): JsonSchema {\n  if (intent === \"price\") return { type: \"object\", required: [\"sku\", \"currency\", \"price\"], properties: { sku: { type: \"string\", minLength: 2 }, currency: { type: \"string\", minLength: 3 }, price: { type: \"number\", minimum: 0 } } };\n  if (intent === \"news\") return { type: \"object\", required: [\"supplier\", \"severity\", \"sentiment\"], properties: { supplier: { type: \"string\" }, severity: { type: \"string\" }, sentiment: { type: \"string\" } } };\n  if (intent === \"compliance\") return { type: \"object\", required: [\"framework\", \"controlId\", \"status\"], properties: { framework: { type: \"string\" }, controlId: { type: \"string\" }, status: { type: \"string\" } } };\n  if (intent === \"lead\") return { type: \"object\", required: [\"domain\", \"email\"], properties: { domain: { type: \"string\", minLength: 3 }, email: { type: \"string\", minLength: 5 } } };\n  if (intent === \"vat\") return { type: \"object\", required: [\"hs\", \"euVat\", \"ukVat\", \"landedUsd\", \"compliant\"], properties: { hs: { type: \"string\" }, euVat: { type: \"number\" }, ukVat: { type: \"number\" }, landedUsd: { type: \"number\" }, compliant: { type: \"boolean\" } } };\n  if (intent === \"outage\") return { type: \"object\", required: [\"sev\", \"provider\", \"region\", \"incidentId\", \"pageDegraded\"], properties: { sev: { type: \"string\" }, provider: { type: \"string\" }, region: { type: \"string\" }, incidentId: { type: \"string\" }, pageDegraded: { type: \"boolean\" } } };\n  if (intent === \"leak\") return { type: \"object\", required: [\"domain\", \"findings\", \"redacted\", \"ticket\"], properties: { domain: { type: \"string\" }, findings: { type: \"number\" }, redacted: { type: \"boolean\" }, ticket: { type: \"string\" } } };\n  return { type: \"object\", required: [\"winner\", \"vendors\", \"deltaUsd\", \"complete\"], properties: { winner: { type: \"string\" }, vendors: { type: \"number\" }, deltaUsd: { type: \"number\" }, complete: { type: \"boolean\" } } };\n}\nexport function restFor(intent: Intent): RestSpec {\n  if (intent === \"price\") return { method: \"POST\", url: \"https://erp.internal/webhooks/price-delta\", headers: { \"X-Idempotency-Key\": \"nr-price\" } };\n  if (intent === \"news\") return { method: \"POST\", url: \"https://hooks.slack.internal/nr\", headers: { \"Content-Type\": \"application/json\" } };\n  if (intent === \"compliance\") return { method: \"POST\", url: \"https://audit.internal/v1/events\", headers: { \"X-Control-Plane\": \"noul\" } };\n  if (intent === \"lead\") return { method: \"PUT\", url: \"https://crm.internal/api/leads/upsert\", headers: { \"X-Object\": \"Lead\" } };\n  if (intent === \"vat\") return { method: \"POST\", url: \"https://sap.internal/api/tax/landed-cost\", headers: { \"X-SAP-Object\": \"LandedCost\" } };\n  if (intent === \"outage\") return { method: \"POST\", url: \"https://api.pagerduty.internal/incidents\", headers: { From: \"nexusrelay@ops.internal\" } };\n  if (intent === \"leak\") return { method: \"POST\", url: \"https://secops.internal/api/tickets\", headers: { \"X-Queue\": \"identity-threat\" } };\n  return { method: \"POST\", url: \"https://exec.internal/api/summaries\", headers: { \"X-Doc-Type\": \"rfp-matrix\" } };\n}\nexport function synthesize(objective: string): WorkflowDag {\n  const intent = detectIntent(objective);\n  const schema = schemaFor(intent);\n  const rest = restFor(intent);\n  const nodes: WorkflowNode[] = [\n    { id: \"scout\", title: \"Scout the scene\", channel: \"TAVILY_RESEARCH\", mind: \"scout\", dependsOn: [], pruneBudget: 720, prompt: objective, jev: { scoreMin: 0.62, choice: [\"proceed\", \"retry_extract\", \"abort\"], noul: null } },\n    { id: \"extract\", title: \"Shape the payload\", channel: \"TRANSFORMATION\", mind: \"extractor\", dependsOn: [\"scout\"], pruneBudget: 480, prompt: \"Extract structured clues\", jev: { scoreMin: 0.7, choice: [\"proceed\", \"human_review\", \"abort\"], noul: schema } },\n    { id: \"gate\", title: \"Verify the evidence\", channel: \"HUMAN_GATE\", mind: \"gatekeeper\", dependsOn: [\"extract\"], pruneBudget: 240, prompt: \"Check the result against the goal\", jev: { scoreMin: 0.72, choice: [\"proceed\", \"human_review\", \"abort\"], noul: schema } },\n    { id: \"settle\", title: \"Deliver the result\", channel: \"REST_API_DISPATCH\", mind: \"settlement\", dependsOn: [\"gate\"], pruneBudget: 200, prompt: \"Prepare the result for the user\", rest, jev: { scoreMin: 0.65, choice: [\"proceed\", \"abort\"], noul: { type: \"object\", required: [\"ok\"], properties: { ok: { type: \"boolean\" } } } } }\n  ];\n  return { id: \"dag_\" + intent, objective, intent, nodes, edges: [[\"scout\", \"extract\"], [\"extract\", \"gate\"], [\"gate\", \"settle\"]] };\n}\nexport function topo(dag: WorkflowDag): WorkflowNode[] {\n  const byId = Object.fromEntries(dag.nodes.map(n => [n.id, n]));\n  if (Object.keys(byId).length !== dag.nodes.length) throw new Error(\"Duplicate node ID in DAG\");\n  const seen = new Set<string>(); const visiting = new Set<string>(); const out: WorkflowNode[] = [];\n  const visit = (id: string) => {\n    if (visiting.has(id)) throw new Error(\"Cycle in DAG at \" + id);\n    if (seen.has(id)) return;\n    const n = byId[id];\n    if (!n) throw new Error(\"Unknown DAG dependency: \" + id);\n    visiting.add(id);\n    n.dependsOn.forEach(visit);\n    visiting.delete(id);\n    seen.add(id);\n    out.push(n);\n  };\n  for (const [from, to] of dag.edges) {\n    if (!byId[from] || !byId[to] || !byId[to].dependsOn.includes(from)) throw new Error(\"Invalid DAG edge: \" + from + \" -> \" + to);\n  }\n  dag.nodes.forEach(n => visit(n.id));\n  return out;\n}\nfunction sleep(ms: number){ return new Promise(r => setTimeout(r, ms)); }\nexport type VesselTick = { type: \"node\"; node: WorkflowNode } | { type: \"gate\"; node: WorkflowNode } | { type: \"halt\"; node: WorkflowNode } | { type: \"done\" };\nexport async function runVessel(dag: WorkflowDag, onTick: (e: VesselTick) => void): Promise<VesselResult> {\n  let ctx: { markdown: string; structured: Record<string, unknown> | null } = { markdown: \"\", structured: null };\n  const steps: VesselResult[\"steps\"] = []; let totalIn = 0, totalOut = 0, lastScore = 0;\n  let lastChoice: VesselResult[\"lastChoice\"] = null; let lastNoul: VesselResult[\"lastNoul\"] = null;\n  for (const node of topo(dag)) {\n    onTick({ type: \"node\", node }); await sleep(40);\n    let out: VesselResult[\"steps\"][number][\"out\"] = { ok: true, rawTokens: 400, tokens: 200, dropped: 200, markdown: ctx.markdown, structured: ctx.structured };\n    if (node.channel === \"TAVILY_RESEARCH\") {\n      const docs = await tavilySearch(dag.objective);\n      const pruned = pruneTokens(docs, dag.objective, node.pruneBudget);\n      out = { ok: true, rawTokens: docs.reduce((a, d) => a + tokensOf(d.markdown), 0), tokens: pruned.tokens, dropped: pruned.dropped, markdown: pruned.markdown, structured: null, sources: pruned.sources };\n    } else if (node.channel === \"TRANSFORMATION\") {\n      const structured = liftStructured(ctx.markdown, dag.intent);\n      out = { ok: true, rawTokens: tokensOf(ctx.markdown), tokens: tokensOf(JSON.stringify(structured)), dropped: 0, markdown: ctx.markdown, structured };\n    } else if (node.channel === \"REST_API_DISPATCH\") {\n      const body = { ok: true, acceptedAt: new Date().toISOString(), route: node.rest?.url ?? \"\", payload: ctx.structured };\n      out = { ok: true, rawTokens: 90, tokens: tokensOf(JSON.stringify(body)), dropped: 0, markdown: \"\", structured: body, restStatus: 201, rest: node.rest };\n    }\n    totalIn += out.rawTokens; totalOut += out.tokens;\n    const payload = out.structured ?? { markdown: out.markdown };\n    const sc = await jevScore(payload, { required: Object.keys(payload) });\n    const nu = node.jev.noul ? await jevNoul(payload, node.jev.noul) : { pass: true, violations: [] as string[] };\n    const ch = await jevChoice(node.jev.choice, { score: sc.value, scoreMin: node.jev.scoreMin, noul: nu });\n    lastScore = sc.value; lastChoice = ch; lastNoul = nu;\n    steps.push({ node, out, score: sc, noul: nu, choice: ch, at: Date.now() });\n    onTick({ type: \"gate\", node });\n    if (!nu.pass || ch.selected !== \"proceed\") { onTick({ type: \"halt\", node }); return { ok: false, steps, totalIn, totalOut, lastScore, lastChoice, lastNoul }; }\n    ctx = { markdown: out.markdown || ctx.markdown, structured: out.structured || ctx.structured };\n  }\n  onTick({ type: \"done\" });\n  return { ok: true, steps, totalIn, totalOut, lastScore, lastChoice, lastNoul, structured: ctx.structured };\n}\nexport function simulateMonolith(dag: WorkflowDag, vessel: VesselResult) {\n  const hops = dag.nodes.length;\n  const tokens = Math.round((vessel.totalIn || 1800) * (1.85 + hops * 0.35));\n  const drift = Math.max(0, Math.min(1, 0.18 + hops * 0.14 + (1 - (vessel.lastScore || 0.5)) * 0.25));\n  const failAt = drift > 0.55 ? Math.max(1, hops - 1) : null;\n  return { tokens, drift, failAt, hallucination: drift > 0.48, note: failAt ? \"Context pollution at hop \" + failAt : \"Degraded but completed\" };\n}\n","src/core/tavilyAdapter.ts":"import type { Intent } from \"../types\";\nexport interface TavilyDoc { url: string; title: string; markdown: string; }\nconst NOISE = [\"cookie consent\", \"subscribe to newsletter\", \"advertisement slot\"];\nconst CORPUS: Record<Intent, TavilyDoc[]> = {\n  price: [{ url: \"https://vendor-a.example/pricing\", title: \"Widget NX\", markdown: \"SKU NX-428 list USD 428 delta -3.8% currency USD\" }],\n  news: [{ url: \"https://wires.example/risk\", title: \"HelioParts\", markdown: \"HelioParts severity high ETA slip 9 days sentiment negative\" }],\n  compliance: [{ url: \"https://regs.example/dora\", title: \"DORA\", markdown: \"framework DORA controlId ICT-04 status partial\" }],\n  lead: [{ url: \"https://acme-robotics.example\", title: \"Acme\", markdown: \"domain acme-robotics.example email hello@acme-robotics.example employees 180\" }],\n  vat: [{ url: \"https://tariff.example/hs-8471\", title: \"HS 8471\", markdown: \"hs 8471 euVat 0 ukVat 0.02 landedUsd 441.2 compliant true\" }],\n  outage: [{ url: \"https://status.cloud.example\", title: \"AWS\", markdown: \"sev SEV2 provider aws region us-east-1 incidentId INC-4419 pageDegraded true\" }],\n  leak: [{ url: \"https://intel.secops.example/acme\", title: \"Intel\", markdown: \"domain acme-robotics.example findings 2 redacted true ticket SEC-918\" }],\n  rfp: [{ url: \"https://rfp.example/matrix\", title: \"RFP\", markdown: \"winner North vendors 3 deltaUsd -140000 complete true\" }]\n};\nexport function tokensOf(s: string){ return Math.max(1, Math.ceil(String(s||\"\").length / 4)); }\nexport function detectIntent(text: string): Intent {\n  const s = text.toLowerCase();\n  if (/vat|tariff|hs 8471|landed/.test(s)) return \"vat\";\n  if (/outage|pagerduty|multi-cloud|inc-4419/.test(s)) return \"outage\";\n  if (/leak|credential|secops|stealer/.test(s)) return \"leak\";\n  if (/rfp|vendor matrix|line-item/.test(s)) return \"rfp\";\n  if (/price|competitor|sku|delta|erp/.test(s)) return \"price\";\n  if (/supplier|risk|news|slack/.test(s)) return \"news\";\n  if (/regulat|compliance|audit|dora|soc/.test(s)) return \"compliance\";\n  if (/lead|crm|enrich|domain/.test(s)) return \"lead\";\n  return \"price\";\n}\nexport function selectCorpus(q: string){ return CORPUS[detectIntent(q)]; }\nexport function pruneTokens(docs: TavilyDoc[], query: string, budget = 900) {\n  const qset = new Set(query.toLowerCase().match(/[a-z0-9]+/g) ?? []);\n  const sentences: { sent: string; weight: number; url: string }[] = [];\n  for (const d of docs) {\n    const parts = (d.title + \". \" + d.markdown).split(/\\. /);\n    for (const sent of parts) {\n      const low = sent.toLowerCase();\n      if (NOISE.some(n => low.includes(n))) continue;\n      const toks = low.match(/[a-z0-9]+/g) ?? [];\n      sentences.push({ sent: sent.trim(), weight: toks.filter(t => qset.has(t)).length, url: d.url });\n    }\n  }\n  sentences.sort((a,b) => b.weight - a.weight);\n  let used = 0; const kept: typeof sentences = [];\n  for (const s of sentences) { const t = tokensOf(s.sent); if (used + t > budget) continue; kept.push(s); used += t; }\n  const raw = docs.reduce((a,d) => a + tokensOf(d.markdown), 0);\n  return { markdown: kept.map(k => \"- \" + k.sent).join(\"\\n\"), tokens: used, dropped: Math.max(0, raw - used), sources: [...new Set(kept.map(k => k.url))] };\n}\nexport async function tavilySearch(query: string){ return selectCorpus(query); }\nexport async function tavilyExtract(urls: string[]): Promise<TavilyDoc[]> { return selectCorpus(urls.join(\" \")); }\nexport function liftStructured(markdown: string, intent: Intent): Record<string, unknown> {\n  const text = markdown.replace(/\\n/g, \" \");\n  const field = (pattern: RegExp) => text.match(pattern)?.[1];\n  const number = (pattern: RegExp) => { const v = field(pattern); return v === undefined ? undefined : Number(v); };\n  const boolean = (pattern: RegExp) => { const v = field(pattern); return v === undefined ? undefined : v === \"true\"; };\n  if (intent === \"price\") return { sku: field(/\\bSKU\\s+([\\w-]+)/i), currency: field(/\\bcurrency\\s+([A-Z]{3})/i), price: number(/\\bUSD\\s+([\\d.]+)/i), deltaPct: number(/\\bdelta\\s+(-?[\\d.]+)/i) };\n  if (intent === \"news\") return { supplier: field(/\\b([A-Z][A-Za-z]+)\\s+severity/), severity: field(/\\bseverity\\s+(\\w+)/i), sentiment: field(/\\bsentiment\\s+(\\w+)/i), etaSlipDays: number(/\\bETA\\s+slip\\s+(\\d+)/i) };\n  if (intent === \"compliance\") return { framework: field(/\\bframework\\s+(\\w+)/i), controlId: field(/\\bcontrolId\\s+([\\w-]+)/i), status: field(/\\bstatus\\s+(\\w+)/i) };\n  if (intent === \"lead\") return { domain: field(/\\bdomain\\s+([\\w.-]+)/i), email: field(/\\bemail\\s+([\\w.+-]+@[\\w.-]+)/i), employees: number(/\\bemployees\\s+(\\d+)/i) };\n  if (intent === \"vat\") return { hs: field(/\\bhs\\s+(\\d+)/i), euVat: number(/\\beuVat\\s+([\\d.]+)/i), ukVat: number(/\\bukVat\\s+([\\d.]+)/i), landedUsd: number(/\\blandedUsd\\s+([\\d.]+)/i), compliant: boolean(/\\bcompliant\\s+(true|false)/i) };\n  if (intent === \"outage\") return { sev: field(/\\bsev\\s+(\\w+)/i), provider: field(/\\bprovider\\s+(\\w+)/i), region: field(/\\bregion\\s+([\\w-]+)/i), incidentId: field(/\\bincidentId\\s+([\\w-]+)/i), pageDegraded: boolean(/\\bpageDegraded\\s+(true|false)/i) };\n  if (intent === \"leak\") return { domain: field(/\\bdomain\\s+([\\w.-]+)/i), findings: number(/\\bfindings\\s+(\\d+)/i), redacted: boolean(/\\bredacted\\s+(true|false)/i), ticket: field(/\\bticket\\s+([\\w-]+)/i) };\n  return { winner: field(/\\bwinner\\s+(\\w+)/i), vendors: number(/\\bvendors\\s+(\\d+)/i), deltaUsd: number(/\\bdeltaUsd\\s+(-?[\\d.]+)/i), complete: boolean(/\\bcomplete\\s+(true|false)/i) };\n}\n"};
